CREATE TYPE "DeviceType" AS ENUM ('PHONE','LAPTOP');
CREATE TYPE "PairingStatus" AS ENUM ('PENDING','APPROVED','EXPIRED','REVOKED');
CREATE TYPE "MotionEventType" AS ENUM ('MOTION');
CREATE TABLE "User" ("id" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"displayName" TEXT,"resetTokenHash" TEXT,"resetTokenExpiresAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE TABLE "UserSettings" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"motionSensitivity" INTEGER NOT NULL DEFAULT 35,"alertCooldownSec" INTEGER NOT NULL DEFAULT 30,"recordingDurationSec" INTEGER NOT NULL DEFAULT 30,"alarmEnabled" BOOLEAN NOT NULL DEFAULT true,"alarmVolume" INTEGER NOT NULL DEFAULT 70,"notificationsEnabled" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "UserSettings_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "UserSettings_userId_key" ON "UserSettings"("userId");
CREATE TABLE "Device" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"name" TEXT NOT NULL,"type" "DeviceType" NOT NULL,"userAgent" TEXT,"lastSeenAt" TIMESTAMP(3),"isOnline" BOOLEAN NOT NULL DEFAULT false,"cameraPermission" BOOLEAN NOT NULL DEFAULT false,"motionEnabled" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Device_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Pairing" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"cameraDeviceId" TEXT NOT NULL,"viewerDeviceId" TEXT,"codeHash" TEXT NOT NULL,"qrTokenHash" TEXT NOT NULL,"status" "PairingStatus" NOT NULL DEFAULT 'PENDING',"expiresAt" TIMESTAMP(3) NOT NULL,"approvedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Pairing_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CameraSession" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"deviceId" TEXT NOT NULL,"sessionTokenHash" TEXT NOT NULL,"startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"endedAt" TIMESTAMP(3),CONSTRAINT "CameraSession_pkey" PRIMARY KEY ("id"));
CREATE TABLE "MotionEvent" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"deviceId" TEXT NOT NULL,"type" "MotionEventType" NOT NULL DEFAULT 'MOTION',"detectedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"recordingId" TEXT,"notificationSent" BOOLEAN NOT NULL DEFAULT false,CONSTRAINT "MotionEvent_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Recording" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"deviceId" TEXT NOT NULL,"motionEventId" TEXT,"filePath" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"durationSec" INTEGER,"fileSize" INTEGER,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Recording_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PushSubscription" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"endpoint" TEXT NOT NULL,"p256dh" TEXT NOT NULL,"auth" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PushSubscription_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "PushSubscription_endpoint_key" ON "PushSubscription"("endpoint");
ALTER TABLE "UserSettings" ADD CONSTRAINT "UserSettings_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Device" ADD CONSTRAINT "Device_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Pairing" ADD CONSTRAINT "Pairing_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Pairing" ADD CONSTRAINT "Pairing_cameraDeviceId_fkey" FOREIGN KEY ("cameraDeviceId") REFERENCES "Device"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Pairing" ADD CONSTRAINT "Pairing_viewerDeviceId_fkey" FOREIGN KEY ("viewerDeviceId") REFERENCES "Device"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "CameraSession" ADD CONSTRAINT "CameraSession_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CameraSession" ADD CONSTRAINT "CameraSession_deviceId_fkey" FOREIGN KEY ("deviceId") REFERENCES "Device"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "MotionEvent" ADD CONSTRAINT "MotionEvent_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "MotionEvent" ADD CONSTRAINT "MotionEvent_deviceId_fkey" FOREIGN KEY ("deviceId") REFERENCES "Device"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "MotionEvent" ADD CONSTRAINT "MotionEvent_recordingId_fkey" FOREIGN KEY ("recordingId") REFERENCES "Recording"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Recording" ADD CONSTRAINT "Recording_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Recording" ADD CONSTRAINT "Recording_deviceId_fkey" FOREIGN KEY ("deviceId") REFERENCES "Device"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "PushSubscription" ADD CONSTRAINT "PushSubscription_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;